/****************************************************************************
 * app/home_scense/doubao/voice_player.c
 * Streaming PCM playback backed by NuttX nxaudio.
 *
 * 缓冲设计(替代原 pipe 方案):
 *  网络与声卡之间用应用层环形缓冲(内存)解耦,不依赖 NuttX pipe。原 pipe
 *  容量固定 256B(CONFIG_DEV_PIPE_SIZE)且无法运行时放大(F_SETPIPE_SZ /
 *  PIPEIOC_SETSIZE 在本板均返回 EINVAL),导致 TTS 音频只能一点点挤过 →
 *  声卡欠载(Xrun)→ 播放中途断,且 sunxi 驱动在欠载→STOP 时会 Data abort。
 *
 *  本实现:
 *   - 大环形缓冲(RING_CAP)吸收 WebSocket 突发到达与网络抖动;
 *   - 启动前预缓冲(PREBUFFER)攒够纵深再启动声卡,避免启动即欠载;
 *   - 缓冲临时为空且流未结束时喂静音(而非让声卡欠载),根治驱动崩溃,
 *     代价仅是网络严重卡顿时插入极短静音;
 *   - close 时先置 finished,等缓冲播完(COMPLETE)再 nxaudio_stop,
 *     大缓冲下不能立即 stop 否则会截断已缓冲但未播放的尾音。
 ****************************************************************************/

#include "voice_player.h"

#include <nuttx/audio/audio.h>
#include <audioutils/nxaudio.h>

#include <errno.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

/* 环形缓冲容量:≈5.4s @ 24kHz/16bit/mono。TTS 一轮回复通常 <150KB,
 * 攒得下整段;写满时 voice_player_write 阻塞(正常流控,随播放腾空)。 */
#define RING_CAP            (256 * 1024)

/* 启动前预缓冲:攒够 48KB(≈1s)或等满 PREBUFFER_MS 或流已结束再启动声卡。 */
#define PREBUFFER_BYTES     (48 * 1024)
#define PREBUFFER_MS        600

/* close 时等缓冲播完的兜底上限(ms);正常靠 COMPLETE 提前结束。 */
#define DRAIN_MAX_MS        20000

struct voice_player_s
{
  struct nxaudio_s audio;
  pthread_t        thread;
  pthread_mutex_t  lock;
  pthread_cond_t   cond;          /* 数据可用/空间可用/状态变化 */
  uint8_t         *ring;
  size_t           cap;
  size_t           head;          /* 读位置 */
  size_t           tail;          /* 写位置 */
  size_t           count;         /* 已缓冲字节数 */
  volatile int     running;       /* 播放线程运行中 */
  volatile int     aborted;       /* 立即中止(丢弃缓冲) */
  volatile int     finished;      /* 写端已关闭,无更多数据 */
  int              audio_initialized;
};

static uint64_t now_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
}

/* 从环形缓冲取最多 max 字节到 dst,返回实际取出字节数(需持锁调用)。 */
static size_t ring_pull(voice_player_t *p, uint8_t *dst, size_t max)
{
  size_t n = p->count < max ? p->count : max;
  size_t first;

  if (n == 0)
    {
      return 0;
    }
  first = p->cap - p->head;
  if (first > n)
    {
      first = n;
    }
  memcpy(dst, p->ring + p->head, first);
  if (n > first)
    {
      memcpy(dst + first, p->ring, n - first);
    }
  p->head = (p->head + n) % p->cap;
  p->count -= n;
  return n;
}

static void player_dequeue(unsigned long arg, struct ap_buffer_s *buffer)
{
  voice_player_t *player = (voice_player_t *)(uintptr_t)arg;
  size_t got;

  if (!player || !buffer)
    {
      return;
    }

  if (player->aborted)
    {
      buffer->nbytes = 0;    /* 丢弃在途音频,尽快静音收尾 */
      return;
    }

  pthread_mutex_lock(&player->lock);
  /* 缓冲空且流未结束:短暂等数据到达(最多 100ms),避免立即喂静音。 */
  if (player->count == 0 && !player->finished && !player->aborted)
    {
      struct timespec ts;
      clock_gettime(CLOCK_REALTIME, &ts);
      ts.tv_nsec += 100 * 1000000L;
      if (ts.tv_nsec >= 1000000000L) { ts.tv_sec++; ts.tv_nsec -= 1000000000L; }
      pthread_cond_timedwait(&player->cond, &player->lock, &ts);
    }
  got = ring_pull(player, buffer->samp, buffer->nmaxbytes);
  pthread_mutex_unlock(&player->lock);

  if (got > 0)
    {
      pthread_cond_signal(&player->cond);   /* 唤醒可能阻塞的 write */
      buffer->nbytes  = got;
      buffer->curbyte = 0;
      buffer->flags   = 0;
      (void)nxaudio_enqbuffer(&player->audio, buffer);
      return;
    }

  if (player->finished || player->aborted)
    {
      buffer->nbytes = 0;    /* 流结束且缓冲空 → 自然收尾(不再入队) */
      return;
    }

  /* 缓冲临时为空但流未结束:喂一整块静音保持声卡不欠载(防驱动崩溃)。 */
  memset(buffer->samp, 0, buffer->nmaxbytes);
  buffer->nbytes  = buffer->nmaxbytes;
  buffer->curbyte = 0;
  buffer->flags   = 0;
  (void)nxaudio_enqbuffer(&player->audio, buffer);
}

static void player_complete(unsigned long arg)
{
  voice_player_t *player = (voice_player_t *)(uintptr_t)arg;
  if (player)
    {
      player->running = 0;
    }
}

static void player_user(unsigned long arg, struct audio_msg_s *message,
                        bool *running)
{
  (void)arg;
  (void)message;
  (void)running;
}

static void *player_thread(void *arg)
{
  voice_player_t *player = arg;
  struct nxaudio_callbacks_s callbacks =
  {
    player_dequeue,
    player_complete,
    player_user,
  };
  uint64_t start = now_ms();
  int i;

  /* 启动前预缓冲:攒够 PREBUFFER_BYTES 或等满 PREBUFFER_MS 或流已结束。
   * 用自有计数器 count 判断(不依赖 pipe FIONREAD)。 */
  pthread_mutex_lock(&player->lock);
  while (!player->aborted && !player->finished &&
         player->count < PREBUFFER_BYTES &&
         now_ms() - start < PREBUFFER_MS)
    {
      struct timespec ts;
      clock_gettime(CLOCK_REALTIME, &ts);
      ts.tv_nsec += 20 * 1000000L;
      if (ts.tv_nsec >= 1000000000L) { ts.tv_sec++; ts.tv_nsec -= 1000000000L; }
      pthread_cond_timedwait(&player->cond, &player->lock, &ts);
    }
  pthread_mutex_unlock(&player->lock);

  for (i = 0; i < player->audio.abufnum; i++)
    {
      player_dequeue((unsigned long)(uintptr_t)player, player->audio.abufs[i]);
    }

  (void)nxaudio_start(&player->audio);
  (void)nxaudio_msgloop(&player->audio, &callbacks,
                        (unsigned long)(uintptr_t)player);
  player->running = 0;
  return NULL;
}

int voice_player_open(voice_player_t **out, const char *device,
                      uint32_t sample_rate, uint8_t channels,
                      uint8_t bits_per_sample)
{
  voice_player_t *player;
  int ret;

  if (!out || !device)
    {
      return -EINVAL;
    }

  player = calloc(1, sizeof(*player));
  if (!player)
    {
      return -ENOMEM;
    }

  player->ring = malloc(RING_CAP);
  if (!player->ring)
    {
      free(player);
      return -ENOMEM;
    }
  player->cap = RING_CAP;
  pthread_mutex_init(&player->lock, NULL);
  pthread_cond_init(&player->cond, NULL);

  ret = init_nxaudio_devname(&player->audio, sample_rate, bits_per_sample,
                             channels, device, "/doubao_player");
  if (ret < 0)
    {
      fprintf(stderr, "doubao: player init_nxaudio_devname(dev=%s "
              "rate=%lu ch=%u bps=%u) failed: %d\n",
              device, (unsigned long)sample_rate, channels,
              bits_per_sample, ret);
      voice_player_close(player);
      return ret;
    }
  player->audio_initialized = 1;

  player->running = 1;
  ret = pthread_create(&player->thread, NULL, player_thread, player);
  if (ret != 0)
    {
      fprintf(stderr, "doubao: player pthread_create failed: %d\n", ret);
      player->running = 0;
      voice_player_close(player);
      return -ret;
    }

  fprintf(stderr, "doubao: player opened dev=%s rate=%lu ch=%u bps=%u\n",
          device, (unsigned long)sample_rate, channels, bits_per_sample);
  *out = player;
  return 0;
}

int voice_player_write(voice_player_t *player, const uint8_t *data,
                       size_t size)
{
  size_t written = 0;

  if (!player || !data)
    {
      return -EINVAL;
    }

  pthread_mutex_lock(&player->lock);
  while (written < size && !player->aborted)
    {
      size_t space, n, first;

      /* 缓冲满:等播放腾出空间(正常流控)。 */
      while (player->count == player->cap && !player->aborted)
        {
          pthread_cond_wait(&player->cond, &player->lock);
        }
      if (player->aborted)
        {
          break;
        }

      space = player->cap - player->count;
      n = (size - written) < space ? (size - written) : space;
      first = player->cap - player->tail;
      if (first > n)
        {
          first = n;
        }
      memcpy(player->ring + player->tail, data + written, first);
      if (n > first)
        {
          memcpy(player->ring, data + written + first, n - first);
        }
      player->tail = (player->tail + n) % player->cap;
      player->count += n;
      written += n;
      pthread_cond_signal(&player->cond);   /* 唤醒等数据的 dequeue */
    }
  pthread_mutex_unlock(&player->lock);

  return player->aborted ? -EPIPE : 0;
}

void voice_player_close(voice_player_t *player)
{
  if (!player)
    {
      return;
    }

  /* 置 finished 并广播:让 dequeue 把缓冲剩余数据播完后自然收尾。 */
  pthread_mutex_lock(&player->lock);
  player->finished = 1;
  pthread_cond_broadcast(&player->cond);
  pthread_mutex_unlock(&player->lock);

  /* 等缓冲播完(driver 回 COMPLETE 置 running=0)或超时兜底。abort 路径
   * 已置 aborted,dequeue 立即返回空缓冲,这里会很快结束。 */
  if (player->audio_initialized && player->thread)
    {
      uint64_t start = now_ms();
      while (player->running && now_ms() - start < DRAIN_MAX_MS)
        {
          usleep(20 * 1000);
        }
    }

  /* 无条件发 AUDIO_MSG_STOP 令 msgloop 退出(仅置 running=0 不会跳出
   * mq_receive),否则 pthread_join 永久等待。 */
  if (player->audio_initialized)
    {
      (void)nxaudio_stop(&player->audio);
    }
  if (player->thread)
    {
      (void)pthread_join(player->thread, NULL);
    }
  if (player->audio_initialized)
    {
      fin_nxaudio(&player->audio);
    }
  pthread_cond_destroy(&player->cond);
  pthread_mutex_destroy(&player->lock);
  free(player->ring);
  free(player);
}

void voice_player_abort(voice_player_t *player)
{
  if (!player)
    {
      return;
    }
  /* 立即中止:丢弃缓冲、唤醒阻塞的 write/dequeue,随后走 close 收尾流程
   * (nxaudio_stop 立即停,不 drain 尾音)。 */
  pthread_mutex_lock(&player->lock);
  player->aborted = 1;
  player->count = 0;        /* 丢弃未播放数据 */
  pthread_cond_broadcast(&player->cond);
  pthread_mutex_unlock(&player->lock);
  voice_player_close(player);
}

/****************************************************************************
 * app/home_scense/doubao/voice_player.c
 * Streaming PCM playback backed by NuttX nxaudio.
 *
 * 网络与声卡之间用 pipe 解耦:voice_player_write 写入 pipe,player_thread
 * 从 pipe 读出回填 nxaudio 缓冲。sunxi 驱动内部 PCM 硬件缓冲很小(≈42ms),
 * 故 pipe 与声卡缓冲共同承担抖动吸收;数据自网络实时到达即可平稳播放。
 *
 * 收尾(clean end):voice_player_close 不立即 nxaudio_stop(会丢弃 pendq +
 * 声卡在途数据 → 截断结尾),而是先关 pipe 写端(EOF),轮询等 pipe 排空 +
 * 一小段余量让声卡播完最后几块,再 stop。abort(打断/抢占)才立即 stop。
 ****************************************************************************/

#include "voice_player.h"

#include <nuttx/audio/audio.h>

#include <errno.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <time.h>
#include <unistd.h>

/* 收尾排空:等 pipe 排空的上限,以及 pipe 空后等声卡播完在途缓冲的余量。 */
#define DRAIN_MAX_MS    20000
#define DRAIN_TAIL_MS   500

struct voice_player_s
{
  struct nxaudio_s audio;
  int read_fd;
  int write_fd;
  pthread_t thread;
  volatile int running;
  volatile int aborted;   /* abort 请求:dequeue 回调停止回填,尽快静音 */
  int audio_initialized;
};

static uint64_t now_ms(void)
{
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
}

static void player_dequeue(unsigned long arg, struct ap_buffer_s *buffer)
{
  voice_player_t *player = (voice_player_t *)(uintptr_t)arg;
  ssize_t received;

  if (!player || !buffer)
    {
      return;
    }

  /* abort 后不再回填:直接交回空缓冲,让播放尽快停下(不再把在途 TTS
   * 灌进声卡)。 */
  if (player->aborted)
    {
      buffer->nbytes = 0;
      return;
    }

  received = read(player->read_fd, buffer->samp, buffer->nmaxbytes);
  if (received <= 0)
    {
      buffer->nbytes = 0;
      return;
    }

  buffer->nbytes = received;
  buffer->curbyte = 0;
  buffer->flags = 0;
  (void)nxaudio_enqbuffer(&player->audio, buffer);
}

static void player_complete(unsigned long arg)
{
  voice_player_t *player = (voice_player_t *)(uintptr_t)arg;
  if (player)
    {
      player->running = 0;
    }
}

static void player_user(unsigned long arg, struct audio_msg_s *message,
                        bool *running)
{
  (void)arg;
  (void)message;
  (void)running;
}

static void *player_thread(void *arg)
{
  voice_player_t *player = arg;
  struct nxaudio_callbacks_s callbacks =
  {
    player_dequeue,
    player_complete,
    player_user,
  };
  int i;

  for (i = 0; i < player->audio.abufnum; i++)
    {
      player_dequeue((unsigned long)(uintptr_t)player, player->audio.abufs[i]);
    }

  (void)nxaudio_start(&player->audio);
  (void)nxaudio_msgloop(&player->audio, &callbacks,
                        (unsigned long)(uintptr_t)player);
  player->running = 0;
  return NULL;
}

int voice_player_open(voice_player_t **out, const char *device,
                      uint32_t sample_rate, uint8_t channels,
                      uint8_t bits_per_sample)
{
  voice_player_t *player;
  int fds[2];
  int ret;

  if (!out || !device)
    {
      return -EINVAL;
    }

  player = calloc(1, sizeof(*player));
  if (!player)
    {
      return -ENOMEM;
    }
  player->read_fd = -1;
  player->write_fd = -1;

  if (pipe(fds) < 0)
    {
      fprintf(stderr, "doubao: player pipe() failed: %d\n", errno);
      free(player);
      return -errno;
    }
  player->read_fd = fds[0];
  player->write_fd = fds[1];

  ret = init_nxaudio_devname(&player->audio, sample_rate, bits_per_sample,
                             channels, device, "/doubao_player");
  if (ret < 0)
    {
      fprintf(stderr, "doubao: player init_nxaudio_devname(dev=%s "
              "rate=%lu ch=%u bps=%u) failed: %d\n",
              device, (unsigned long)sample_rate, channels,
              bits_per_sample, ret);
      voice_player_close(player);
      return ret;
    }
  player->audio_initialized = 1;

  player->running = 1;
  ret = pthread_create(&player->thread, NULL, player_thread, player);
  if (ret != 0)
    {
      fprintf(stderr, "doubao: player pthread_create failed: %d\n", ret);
      voice_player_close(player);
      return -ret;
    }

  fprintf(stderr, "doubao: player opened dev=%s rate=%lu ch=%u bps=%u\n",
          device, (unsigned long)sample_rate, channels, bits_per_sample);
  *out = player;
  return 0;
}

int voice_player_write(voice_player_t *player, const uint8_t *data,
                       size_t size)
{
  size_t written = 0;

  if (!player || !data)
    {
      return -EINVAL;
    }

  while (written < size)
    {
      ssize_t ret = write(player->write_fd, data + written, size - written);
      if (ret <= 0)
        {
          return -errno;
        }
      written += ret;
    }

  return 0;
}

void voice_player_close(voice_player_t *player)
{
  if (!player)
    {
      return;
    }

  /* 关 pipe 写端:player_dequeue 的 read 将读到 EOF(返回 0)。 */
  if (player->write_fd >= 0)
    {
      close(player->write_fd);
      player->write_fd = -1;
    }

  /* clean end:非 abort 时先等 pipe 排空 + 一小段余量,让声卡把已回填的
   * 数据(含最后几块)播完再 stop,避免 nxaudio_stop 丢弃 pendq 截断结尾。
   * abort 路径 aborted=1,dequeue 立即交空缓冲,跳过排空直接 stop。 */
  if (!player->aborted && player->read_fd >= 0)
    {
      uint64_t start = now_ms();
      int pending = 0;
      while (now_ms() - start < DRAIN_MAX_MS)
        {
          if (ioctl(player->read_fd, FIONREAD,
                    (unsigned long)(uintptr_t)&pending) < 0)
            {
              break;      /* 查询失败:放弃排空,直接收尾 */
            }
          if (pending <= 0)
            {
              break;      /* pipe 已空,数据都已交给声卡 */
            }
          usleep(20 * 1000);
        }
      /* pipe 空后,声卡缓冲(≤2 块)仍在播,给一小段余量播完。 */
      usleep(DRAIN_TAIL_MS * 1000);
    }

  /* 必须无条件发 AUDIO_MSG_STOP:nxaudio_msgloop 只在收到 STOP 时才退出,
   * 播放自然结束(AUDIO_MSG_COMPLETE)只把回调里的 running 置 0,并不会让
   * msgloop 跳出——它会继续阻塞在 mq_receive。若跳过 nxaudio_stop,后面的
   * pthread_join 会永久等待,worker 卡在 mq_receive,整个语音功能死锁。 */
  if (player->audio_initialized)
    {
      (void)nxaudio_stop(&player->audio);
    }
  if (player->thread)
    {
      (void)pthread_join(player->thread, NULL);
    }
  if (player->read_fd >= 0)
    {
      close(player->read_fd);
    }
  if (player->audio_initialized)
    {
      fin_nxaudio(&player->audio);
    }
  free(player);
}

void voice_player_abort(voice_player_t *player)
{
  if (!player)
    {
      return;
    }
  /* 置 abort:dequeue 回调停止从管道回填数据,在途 TTS 被丢弃;随后走与
   * close 相同的停止/回收流程(nxaudio_stop 立即停,不 drain 尾音)。 */
  player->aborted = 1;
  voice_player_close(player);
}

